    check('mine: tiers match the node heights and the chamber nodes sit on their tier', M.NODES.every(n => M.tierOf(n.y) === M.GEOM.TIERS.indexOf(n.y) + 1 || (n.y === 0 && M.tierOf(n.y) === 0)) && M.tierOf(0) === 0 && M.tierOf(3.9) === 1 && M.tierOf(20.2) === 4 && M.nearestNode(-15.5, 5, 0) === M.IDX.CHA && M.nearestNode(0, 0, 0) === M.IDX.F0);
    check('mine: the farthest node from the start is on the top floor and the skip list is respected', M.NODES[M.farthestNode(0, 0, 6.5)].y >= 10 && M.farthestNode(0, 0, 6.5, [M.farthestNode(0, 0, 6.5)]) !== M.farthestNode(0, 0, 6.5));
    check('mine: the lamp battery drains only while lit, recharges to 100% at most, and dims and flickers when low', M.batteryStep(1, 10, true, 100) === 0.9 && M.batteryStep(0.5, 10, false, 100) === 0.5 && M.batteryStep(0.01, 99, true, 100) === 0 && M.batteryAdd(0.8, 0.45) === 1 && M.lampReach(0) === 0 && M.lampReach(1) === 1 && M.lampReach(0.2) < M.lampReach(0.4) && M.lampFlickers(0.05, 0.1) && !M.lampFlickers(0.5, 0.1) && !M.lampFlickers(0, 0.1) && M.lampSeconds('easy') > M.lampSeconds('normal') && M.lampSeconds('normal') > M.lampSeconds('nightmare') && M.lampSeconds('x') === M.lampSeconds('normal'));
