    check('mine: the Digger is faster in a chase than on patrol, slower on a ladder, and the difficulty scales it', M.speedFor('chase', 'walk', 'normal') > M.speedFor('investigate', 'walk', 'normal') && M.speedFor('investigate', 'walk', 'normal') > M.speedFor('patrol', 'walk', 'normal') && M.speedFor('chase', 'ladder', 'normal') < M.speedFor('chase', 'walk', 'normal') && M.speedFor('chase', 'walk', 'nightmare') > M.speedFor('chase', 'walk', 'normal') && M.speedFor('chase', 'walk', 'easy') < M.speedFor('chase', 'walk', 'normal') && M.speedFor('chase', 'walk', 'normal') < 4.5);
